"""Demonstrate test-time compute scaling and reasoning verification."""

from __future__ import annotations

from collections import Counter
from dataclasses import dataclass
import random


@dataclass(frozen=True)
class ReasoningStep:
    """A single step in a multi-step chain-of-thought reasoning path."""

    step_index: int
    thought: str
    intermediate_result: float
    is_valid: bool


@dataclass(frozen=True)
class CandidateSolution:
    """A complete candidate solution generated by an LLM."""

    candidate_id: int
    steps: list[ReasoningStep]
    final_answer: float

    @property
    def is_fully_valid(self) -> bool:
        """Check if every reasoning step is logically sound."""
        return all(step.is_valid for step in self.steps)


def evaluate_outcome_reward(solution: CandidateSolution, ground_truth: float) -> float:
    """Outcome Reward Model (ORM): score only the final answer."""
    return 1.0 if abs(solution.final_answer - ground_truth) < 1e-4 else 0.0


def evaluate_process_reward(solution: CandidateSolution) -> float:
    """Process Reward Model (PRM): score step-by-step reasoning quality."""
    if not solution.steps:
        return 0.0
    valid_count = sum(1.0 for step in solution.steps if step.is_valid)
    return valid_count / len(solution.steps)


def simulate_model_inference(
    question: str,
    ground_truth: float,
    *,
    candidate_id: int,
    error_rate: float = 0.35,
    rng: random.Random,
) -> CandidateSolution:
    """Simulate a language model generating a multi-step solution.

    With probability `error_rate`, one intermediate step slips up.
    """
    del question, ground_truth  # The synthetic generator does not use the evaluation answer.
    steps: list[ReasoningStep] = []

    # Step 1: Base quantity setup
    step1_valid = rng.random() > error_rate * 0.4
    val1 = 24.0 if step1_valid else 20.0
    steps.append(
        ReasoningStep(
            step_index=1,
            thought="计算第一天工人的生产基数 (目标产出 24 件)",
            intermediate_result=val1,
            is_valid=step1_valid,
        )
    )

    # Step 2: Rate scaling
    step2_valid = rng.random() > error_rate * 0.5
    factor = 1.5 if step2_valid else 1.2
    val2 = val1 * factor
    steps.append(
        ReasoningStep(
            step_index=2,
            thought=f"根据提效系数 {factor} 放大产能",
            intermediate_result=val2,
            is_valid=step2_valid and step1_valid,
        )
    )

    # Step 3: Shift deductions
    step3_valid = rng.random() > error_rate * 0.5
    offset = 4.0 if step3_valid else 2.0
    final_val = val2 - offset
    steps.append(
        ReasoningStep(
            step_index=3,
            thought=f"扣除质检损耗 {offset} 件得到净产量",
            intermediate_result=final_val,
            is_valid=step3_valid and step2_valid and step1_valid,
        )
    )

    return CandidateSolution(
        candidate_id=candidate_id,
        steps=steps,
        final_answer=final_val,
    )


def self_consistency_voting(candidates: list[CandidateSolution]) -> tuple[float, float]:
    """Return the majority answer and its vote share, not calibrated confidence."""
    if not candidates:
        raise ValueError("Voting requires at least one candidate.")
    answers = [cand.final_answer for cand in candidates]
    counts = Counter(answers)
    majority_answer, occurrences = counts.most_common(1)[0]
    confidence = occurrences / len(candidates)
    return majority_answer, confidence


def self_correction_loop(
    initial_solution: CandidateSolution,
) -> CandidateSolution:
    """Recompute this fixed arithmetic problem with a deterministic rule checker."""
    base = 24.0
    scaled = base * 1.5
    revised_answer = scaled - 4.0
    revised_steps = [
        ReasoningStep(1, "[规则复算] 从题面读取基数 24", base, True),
        ReasoningStep(2, "[规则复算] 乘以提效系数 1.5", scaled, True),
        ReasoningStep(3, "[规则复算] 扣除损耗 4", revised_answer, True),
    ]
    return CandidateSolution(
        candidate_id=initial_solution.candidate_id + 100,
        steps=revised_steps,
        final_answer=revised_answer,
    )


def main() -> int:
    rng = random.Random(42)
    question = "工厂生产调度问题：基数 24，效率提升 1.5 倍，损耗 4 件，最终净产量是多少？"
    ground_truth = 24.0 * 1.5 - 4.0  # 32.0

    print("=" * 65)
    print("测试时计算扩展 (Test-Time Compute Scaling) 机制演示")
    print("=" * 65)
    print(f"目标问题: {question}")
    print(f"标准真值 (Ground Truth): {ground_truth}\n")

    # 1. Direct Sampling (N = 1, minimal inference compute)
    print("[1. 单次随机模拟采样 (N=1)]")
    single_cand = simulate_model_inference(question, ground_truth, candidate_id=1, rng=rng)
    print(f"  推断步骤数: {len(single_cand.steps)}")
    for s in single_cand.steps:
        mark = "✓" if s.is_valid else "✗ (逻辑错误)"
        print(f"    步骤 {s.step_index}: {s.thought} -> {s.intermediate_result} [{mark}]")
    print(f"  最终输出: {single_cand.final_answer}")
    print(f"  结果正确: {abs(single_cand.final_answer - ground_truth) < 1e-4}\n")

    # 2. Test-time expansion: Best-of-N with PRM vs ORM scoring
    print("[2. 采样多样化扩展 (Best-of-N Sampling, N=8)]")
    n_samples = 8
    candidates = [
        simulate_model_inference(question, ground_truth, candidate_id=i + 1, rng=rng)
        for i in range(n_samples)
    ]

    for c in candidates:
        orm_score = evaluate_outcome_reward(c, ground_truth)
        prm_score = evaluate_process_reward(c)
        print(
            f"  候选 #{c.candidate_id}: 输出={c.final_answer:.1f} | "
            f"PRM 过程得分={prm_score:.2f} | ORM 结果得分={orm_score:.0f}"
        )

    # 3. Majority Voting (Self-Consistency)
    best_candidate = max(candidates, key=evaluate_process_reward)
    print(f"  按模拟过程标签选出的 Best-of-N 候选: #{best_candidate.candidate_id}")
    voted_ans, confidence = self_consistency_voting(candidates)
    print(f"\n[3. 多数自洽投票 (Self-Consistency Voting)]")
    print(f"  投票胜出答案: {voted_ans:.1f} (票数占比: {confidence * 100:.1f}%)")
    print(f"  投票命中真值: {abs(voted_ans - ground_truth) < 1e-4}\n")

    # 4. Self-Correction / Reflection Loop
    print("[4. 慢思考自我反思与批判修正 (Critique & Reflection Loop)]")
    flawed_candidates = [c for c in candidates if not c.is_fully_valid]
    if flawed_candidates:
        target_cand = flawed_candidates[0]
        print(f"  选取引发质疑的候选 #{target_cand.candidate_id} (原输出: {target_cand.final_answer:.1f})")
        corrected = self_correction_loop(target_cand)
        print("  本例由固定算术规则复算；未训练反思模型，也不把标准答案传给修正器。")
        print(f"  修正后输出: {corrected.final_answer:.1f}")
        print(f"  修正是否成功: {abs(corrected.final_answer - ground_truth) < 1e-4}\n")

    # 5. Compute vs Accuracy Trade-off Summary
    print("[5. 推理算力与准确率扩展定律 (Scaling Law Summary)]")
    print("  - 多次采样增加候选生成成本，是否提高准确率取决于候选质量和选择器。")
    print("  - ORM 使用已知答案，PRM 使用模拟器提供的标签；它们是教学评分，不是已训练模型。")
    print("  - 本例没有真实 LLM、Token 计费、耗时测量或准确率基准，不能用于证明扩展定律。")

    return 0


if __name__ == "__main__":
    raise SystemExit(main())
